// HasTimetableSlot applies the HasEdge predicate on the "timetable_slot" edge.
func HasTimetableSlot() predicate.TimetableDeviation {
	return predicate.TimetableDeviation(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TimetableSlotTable, TimetableSlotColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTimetableSlotWith applies the HasEdge predicate on the "timetable_slot" edge with a given conditions (other predicates).
func HasTimetableSlotWith(preds ...predicate.TimetableSlot) predicate.TimetableDeviation {
	return predicate.TimetableDeviation(func(s *sql.Selector) {
		step := newTimetableSlotStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

